// Forms name their file fields after the label, so find the photo whatever it is called
// and move it to a fixed key ('photo') that the next nodes can rely on.
const it = $input.first();
const bin = it.binary || {};
const keys = Object.keys(bin);
const imgs = keys.filter(k => /^image\//.test(bin[k].mimeType || '')).sort();
const pick = keys.find(k => /passport/i.test(k)) || imgs.find(k => !/selfie/i.test(k)) || imgs[0];
