          binary: { photo: bin[pick] } }];

// Claude takes images as base64 (max 5MB), which is why the photo is shrunk first.
const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  let image_b64 = null;
  try { image_b64 = (await this.helpers.getBinaryDataBuffer(i, 'photo')).toString('base64'); } catch (e) {}
  out.push({ json: { ...items[i].json, image_b64, media_type: 'image/jpeg' } });
}
return out;

